<script>

window.Webflow ||= [];

window.Webflow.push(() => {
 
  // Calendar icon hide

  const style = document.createElement("style");

  style.innerHTML = `

    input[type="date"]::-webkit-calendar-picker-indicator{

      opacity:0 !important;

      position:absolute;

      inset:0;

      width:100%;

      height:100%;

      cursor:pointer;

    }

  `;

  document.head.appendChild(style);
 
  // Click anywhere on input = open picker

  document.querySelectorAll('input[type="date"]').forEach((input) => {
 
    input.addEventListener("click", () => {
 
      gsap.fromTo(

        input,

        { scale: 1 },

        {

          scale: 1.02,

          duration: 0.15,

          yoyo: true,

          repeat: 1

        }

      );
 
      if (input.showPicker) {

        input.showPicker();

      }

    });
 
  });
 
});
</script>


